def _validate_trans_variables(
    self,
    variables: t.Dict[str, nodes.Expr],
    parser: "Parser",
    lineno: int,
) -> None:
    """Validate all variables used in a translation block.

    Checks that every variable name is a valid Python identifier that
    does not clash with the translation functions provided by the
    environment, and that the corresponding expression is suitable for
    use in a translation context.
    """
    for name, expr in variables.items():
        if not name.isidentifier():
            parser.fail(
                f"Invalid variable name {name!r} in translation block: "
                f"variable names must be valid Python identifiers",
                lineno,
            )
        if name in GETTEXT_FUNCTIONS:
            parser.fail(
                f"Variable name {name!r} conflicts with translation "
                f"function names and cannot be used as a translation "
                f"variable",
                lineno,
            )
        self._validate_trans_expression(name, expr, parser, lineno)

def _validate_trans_expression(
    self,
    name: str,
    expr: nodes.Expr,
    parser: "Parser",
    lineno: int,
) -> None:
    """Validate a single translation variable expression.

    Only simple expressions that can be substituted into a translated
    string are allowed: literals, variable references, simple function
    calls, attribute access, filters and tests.
    """
    if isinstance(
        expr, (nodes.Const, nodes.Name, nodes.Getattr, nodes.Filter, nodes.Test)
    ):
        return
    if isinstance(expr, nodes.Call) and isinstance(expr.node, nodes.Name):
        return
    if isinstance(expr, (nodes.TemplateData, nodes.Output)):
        parser.fail(
            f"Invalid expression for variable {name!r}: template data "
            f"is not allowed in translation contexts",
            lineno,
        )
    parser.fail(
        f"Invalid expression for variable {name!r}: "
        f"{type(expr).__name__} is a complex expression that cannot be "
        f"used as template data in translation contexts",
        lineno,
    )

def _parse_block(
    self, parser: "Parser", allow_pluralize: bool
) -> t.Tuple[t.List[str], str]:
    """Parse until the next block tag with a given name."""
    referenced = []
    buf = []

    while True:
        if parser.stream.current.type == "data":
            buf.append(parser.stream.current.value.replace("%", "%%"))
            next(parser.stream)
        elif parser.stream.current.type == "variable_begin":
            next(parser.stream)
            name = parser.stream.expect("name").value
            referenced.append(name)
            buf.append(f"%({name})s")
            parser.stream.expect("variable_end")
        elif parser.stream.current.type == "block_begin":
            next(parser.stream)
            if parser.stream.current.test("name:endtrans"):
                break
            elif parser.stream.current.test("name:pluralize"):
                if allow_pluralize:
