from jinja2 import pass_context
from jinja2.exceptions import TemplateSyntaxError

@pass_context
def gettext(context, string):
    return 'T:' + string

@pass_context
def ngettext(context, s, p, n):
    return ('T:' + (p if n != 1 else s))

